mapper.sql:
FROM USER_ACNT U LEFT JOIN OPERATOR_DTL_INFO D ON D.USER_SN = U.USER_SN AND D.DEL_YN = 'N' WHERE U.USER_TYPE_CD = 'OPERATOR' AND U.DEL_YN = 'N'
AND U.ACNT_STTS = #{acntStts}
AND EXISTS ( SELECT 1 FROM USER_ROLE UR JOIN ROLE_MST R ON R.ROLE_SN = UR.ROLE_SN AND R.DEL_YN = 'N' AND R.USE_YN = 'Y' WHERE UR.ACTV_USER_SN = U.USER_SN AND R.ROLE_CD = #{roleCd})

mapper.select:
SELECT 

 ORDER BY U.USER_SN DESC
 LIMIT #{pageSize} OFFSET #{offset}

mapper.update:
UPDATE USER_ROLE UR
  JOIN ROLE_MST R ON R.ROLE_SN = UR.ROLE_SN AND R.ROLE_CD = #{roleCd} AND R.DEL_YN = 'N'
   SET UR.DEL_YN = 'Y',
       UR.MDFCN_DT = UTC_TIMESTAMP(6),
       UR.MDFR_SN = #{mdfrSn}
 WHERE UR.ACTV_USER_SN = #{userSn}

UPDATE USER_ACNT
   SET ACNT_STTS = #{acntStts},
       MDFCN_DT = UTC_TIMESTAMP(6),
       MDFR_SN = #{mdfrSn}
 WHERE USER_SN = #{userSn}
   AND USER_TYPE_CD = 'OPERATOR'
   AND ACNT_STTS = #{expectedStts}
   AND DEL_YN = 'N'

UPDATE OPERATOR_DTL_INFO
   SET MDFCN_DT = UTC_TIMESTAMP(6),
       MDFR_SN = #{mdfrSn}
 , DEPT_NM = #{deptNm} 
 , JBPS_NM = #{jbpsNm} 
 WHERE USER_SN = #{userSn}
   AND DEL_YN = 'N'
